let pipeline=null,extractor=null;const vectors=new Map();let queue=Promise.resolve();
async function embedding(text,maxChunks){const words=text.split(/\s+/),sum=new Float32Array(384);let count=0;for(let start=0;start<words.length&&count<maxChunks;start+=140){const v=(await extractor(words.slice(start,start+160).join(' '),{pooling:'mean',normalize:true,truncation:true})).data;for(let k=0;k<v.length;k++)sum[k]+=v[k];count++;}const length=Math.sqrt(sum.reduce((n,v)=>n+v*v,0))||1;return sum.map(v=>v/length);}
async function run(data){const {id,query,jobs}=data;try{if(!extractor){self.postMessage({id,progress:'Preparing on-device matching…'});const lib=await import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.8.1/+esm');pipeline=lib.pipeline;lib.env.allowLocalModels=false;lib.env.useBrowserCache=true;extractor=await pipeline('feature-extraction','Xenova/all-MiniLM-L6-v2',{dtype:'q8',device:'wasm',progress_callback:p=>{if(p.status==='progress')self.postMessage({id,progress:'Preparing on-device matching: '+Math.round(p.progress||0)+'%'});}});}self.postMessage({id,progress:'Comparing your resume with jobs…'});const q=await embedding(query,20),scores=[];for(let i=0;i<jobs.length;i++){let v=vectors.get(jobs[i]);if(!v){v=await embedding(jobs[i],12);vectors.set(jobs[i],v);if(vectors.size>500)vectors.delete(vectors.keys().next().value);}let score=0;for(let k=0;k<q.length;k++)score+=q[k]*v[k];scores.push(score);if(i%5===0)self.postMessage({id,progress:'Matching jobs on this device: '+(i+1)+'/'+jobs.length});}self.postMessage({id,scores});}catch{self.postMessage({id,error:'The local semantic model could not be loaded.'});}};

self.onmessage=({data})=>{queue=queue.then(()=>run(data)).catch(()=>{});};
